solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <functional>
#include <sstream>
#include <string>
#include <vector>

struct Entry { std::string name; bool dir{ false }; std::uint64_t size{ 0 }; bool reparse{ false }; std::vector<Entry> children; };
struct Options { std::string patterns; bool recurse{ true }; std::uint64_t minSize{ 0 }; bool includeDirs{ false }; int maxDepth{ -1 }; };
struct Found { std::string path; std::uint64_t size; bool dir; };

namespace
{
    char low(char c) { return static_cast<char>(std::tolower(static_cast<unsigned char>(c))); }
    std::string lower(std::string s) { for (char& c : s) c = low(c); return s; }
}

bool wildcardMatch(const std::string& pattern, const std::string& name)
{
    if (pattern == "*.*") return true;
    std::size_t p{ 0 }, n{ 0 }, star{ std::string::npos }, mark{ 0 };
    while (n < name.size())
    {
        if (p < pattern.size() && (pattern[p] == '?' || low(pattern[p]) == low(name[n]))) { ++p; ++n; }
        else if (p < pattern.size() && pattern[p] == '*') { star = p++; mark = n; }
        else if (star != std::string::npos) { p = star + 1; n = ++mark; }      // let the last * swallow one more character
        else return false;
    }
    while (p < pattern.size() && pattern[p] == '*') ++p;
    return p == pattern.size();
}

bool matchesAny(const std::string& patterns, const std::string& name)
{
    bool any{ false };
    std::stringstream in{ patterns };
    for (std::string p; std::getline(in, p, ';');)
    {
        const auto b{ p.find_first_not_of(' ') };
        if (b == std::string::npos) continue;
        any = true;
        if (wildcardMatch(p.substr(b, p.find_last_not_of(' ') - b + 1), name)) return true;
    }
    return !any;
}

namespace
{
    struct Walk
    {
        const Options& options;
        const std::function<bool(int)>& keepGoing;
        std::vector<Found> found;
        int visits{ 0 };

        // Returns false when the search was stopped.
        bool directory(const Entry& dir, const std::string& path, int depth)
        {
            std::vector<const Entry*> entries;
            for (const Entry& e : dir.children) if (e.name != "." && e.name != "..") entries.push_back(&e);
            std::sort(entries.begin(), entries.end(), [](const Entry* a, const Entry* b) {
                const std::string la{ lower(a->name) }, lb{ lower(b->name) };
                return la != lb ? la < lb : a->name < b->name;
            });
            for (const Entry* e : entries)
            {
                const std::string full{ path.empty() || path.back() == '\\' ? path + e->name : path + "\\" + e->name };
                ++visits;
                if (e->dir ? options.includeDirs && matchesAny(options.patterns, e->name)
                           : matchesAny(options.patterns, e->name) && e->size >= options.minSize)
                    found.push_back({ full, e->size, e->dir });
                if (!keepGoing(visits)) return false;
                const bool deeper{ options.maxDepth < 0 || depth < options.maxDepth };
                if (e->dir && options.recurse && !e->reparse && deeper && !directory(*e, full, depth + 1)) return false;
            }
            return true;
        }
    };
}

std::vector<Found> search(const Entry& root, const std::string& rootPath, const Options& options, const std::function<bool(int)>& keepGoing)
{
    Walk w{ options, keepGoing, {}, 0 };
    w.directory(root, rootPath, 1);
    return w.found;
}

unitTests:
Entry file(const std::string& n, std::uint64_t s) { Entry e; e.name = n; e.size = s; return e; }
Entry folder(const std::string& n, std::vector<Entry> c, bool reparse = false) { Entry e; e.name = n; e.dir = true; e.reparse = reparse; e.children = std::move(c); return e; }
const Entry tree = folder("Notes", {
    file("todo.txt", 100), folder("Archive", { file("old.TXT", 50), file("pic.png", 2000), folder("2024", { file("jan.txt", 10) }) }),
    file("readme.md", 30), folder("link", { file("loop.txt", 1) }, true), folder(".", {}), folder("..", {}), file("B.txt", 0) });
std::vector<std::string> paths(const std::vector<Found>& f) { std::vector<std::string> p; for (const auto& x : f) p.push_back(x.path); return p; }
using Paths = std::vector<std::string>;
const auto always = [](int) { return true; };
TEST("wildcards") {
    CHECK(wildcardMatch("*.txt", "notes.TXT")); CHECK(wildcardMatch("?b*", "ab")); CHECK(!wildcardMatch("a?c", "ac")); CHECK(wildcardMatch("*", ""));
    CHECK(wildcardMatch("*a*b", "xaxb")); CHECK(wildcardMatch("a*b*c", "abxbxc")); CHECK(wildcardMatch("*.*", "README")); CHECK(!wildcardMatch("*.txt", "txt")); CHECK(!wildcardMatch("file?.log", "file10.log"));
    CHECK(matchesAny("*.txt; *.MD", "readme.md")); CHECK(!matchesAny("*.txt;*.md", "a.png")); CHECK(matchesAny("", "anything")); CHECK(matchesAny(" ; ", "x"));
}
TEST("a recursive search") {
    Options o; o.patterns = "*.txt"; int visits = 0;
    const auto f = search(tree, "C:\\Notes", o, [&](int n) { visits = n; return true; });
    CHECK_EQ(paths(f), (Paths{ "C:\\Notes\\Archive\\2024\\jan.txt", "C:\\Notes\\Archive\\old.TXT", "C:\\Notes\\B.txt", "C:\\Notes\\todo.txt" })); CHECK_EQ(visits, 9);
    CHECK_EQ(f[3].size, std::uint64_t{ 100 }); CHECK(!f[0].dir);
}
TEST("depth, size and folders") {
    Options top; top.patterns = "*.txt"; top.maxDepth = 1; CHECK_EQ(paths(search(tree, "C:\\Notes", top, always)), (Paths{ "C:\\Notes\\B.txt", "C:\\Notes\\todo.txt" }));
    Options flat; flat.patterns = "*.txt"; flat.recurse = false; CHECK_EQ(search(tree, "C:\\Notes", flat, always).size(), std::size_t{ 2 });
    Options two; two.patterns = "*.txt"; two.maxDepth = 2; CHECK_EQ(search(tree, "C:\\Notes", two, always).size(), std::size_t{ 3 });
    Options big; big.patterns = "*.txt"; big.minSize = 20; CHECK_EQ(paths(search(tree, "C:\\Notes", big, always)), (Paths{ "C:\\Notes\\Archive\\old.TXT", "C:\\Notes\\todo.txt" }));
    Options dirs; dirs.patterns = "a*"; dirs.includeDirs = true; const auto d = search(tree, "C:\\Notes", dirs, always); CHECK_EQ(paths(d), (Paths{ "C:\\Notes\\Archive" })); CHECK(d[0].dir);
    Options all; all.patterns = "*.*"; all.includeDirs = true; CHECK_EQ(search(tree, "C:\\Notes", all, always).size(), std::size_t{ 9 });
}
TEST("stopping and roots") {
    Options o; o.patterns = "*.txt";
    CHECK_EQ(paths(search(tree, "C:\\Notes", o, [](int n) { return n < 4; })), (Paths{ "C:\\Notes\\Archive\\2024\\jan.txt", "C:\\Notes\\Archive\\old.TXT" }));
    CHECK(search(tree, "C:\\Notes", o, [](int) { return false; }).empty());
    Options top; top.patterns = "b*"; top.recurse = false; CHECK_EQ(paths(search(tree, "C:\\", top, always)), (Paths{ "C:\\B.txt" }));
}

